/* From Uiverse.io by SouravBandyopadhyay  - Tags: simple, tooltip, black, clean, submit, transition, hover effect, tailwind */
.__UIV_SCOPE__ .button {
  --width: 100px;
  --height: 35px;
  --tooltip-height: 35px;
  --tooltip-width: 90px;
  --gap-between-tooltip-to-button: 18px;
  --button-color: #222;
  --tooltip-color: #fff;
  width: var(--width);
  height: var(--height);
  background: var(--button-color);
  position: relative;
  text-align: center;
  border-radius: 0.5em;
  font-family: "Arial";
  transition: background 0.7s;
}

.__UIV_SCOPE__ .button::before {
  position: absolute;
  content: attr(data-tooltip);
  width: var(--tooltip-width);
  height: var(--tooltip-height);
  background-color: #555;
  font-size: 0.9rem;
  color: #fff;
  border-radius: 0.25em;
  line-height: var(--tooltip-height);
  bottom: calc(var(--height) + var(--gap-between-tooltip-to-button) + 10px);
  left: calc(50% - var(--tooltip-width) / 2);
}

.__UIV_SCOPE__ .button::after {
  position: absolute;
  content: "";
  width: 0;
  height: 0;
  border: 10px solid transparent;
  border-top-color: #555;
  left: calc(50% - 10px);
  bottom: calc(100% + var(--gap-between-tooltip-to-button) - 10px);
}

.__UIV_SCOPE__ .button::after,
.__UIV_SCOPE__ .button::before {
  opacity: 0;
  visibility: hidden;
  transition: all 0.5s;
}

.__UIV_SCOPE__ .text {
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .button-wrapper,
.__UIV_SCOPE__ .text,
.__UIV_SCOPE__ .icon {
  overflow: hidden;
  position: absolute;
  width: 100%;
  height: 100%;
  left: 0;
  color: #fff;
}

.__UIV_SCOPE__ .text {
  top: 0;
}

.__UIV_SCOPE__ .text,
.__UIV_SCOPE__ .icon {
  transition: top 0.5s;
}

.__UIV_SCOPE__ .icon {
  color: #fff;
  top: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .icon svg {
  width: 24px;
  height: 24px;
}

.__UIV_SCOPE__ .button:hover {
  background: #222;
}

.__UIV_SCOPE__ .button:hover .text {
  top: -100%;
}

.__UIV_SCOPE__ .button:hover .icon {
  top: 0;
}

.__UIV_SCOPE__ .button:hover:before,
.__UIV_SCOPE__ .button:hover:after {
  opacity: 1;
  visibility: visible;
}

.__UIV_SCOPE__ .button:hover:after {
  bottom: calc(var(--height) + var(--gap-between-tooltip-to-button) - 20px);
}

.__UIV_SCOPE__ .button:hover:before {
  bottom: calc(var(--height) + var(--gap-between-tooltip-to-button));
}
